// 150M DAU × 2 posts    → ~3,000 writes/sec
// reads at ~100:1       → ~300,000 reads/sec
//
// → precompute each follower's feed at write time (fan-out on write)

async function createPost(authorId, text) {
  const postId = await ids.next();             // roughly time-sortable
  await db.posts.insert({ postId, authorId, text, createdAt: Date.now() });

  // fan out asynchronously — the author's request returns now
  await queue.publish('fanout', { postId, authorId });

  return postId;
}

async function onFanout({ postId, authorId }) {
  const followers = await db.followers.of(authorId);   // could be millions

  for (const batch of chunk(followers, 500)) {
    await Promise.all(batch.map((uid) =>
      cache.lpushTrim(`feed:${uid}`, postId, 800)      // cap the list
    ));
  }
}

async function getFeed(userId, cursor, limit = 20) {
  const ids = await cache.lrange(`feed:${userId}`, cursor, limit);
  return db.posts.mget(ids);        // hydrate bodies once, on read
}

// author with 10M followers posts:
//   → 10M lpush operations from one event
//   → fan-out workers saturate
//   → ordinary users' posts sit behind it in the queue
//
// Note WHO suffers: not the celebrity. Everyone else.

const CELEBRITY = 100_000;   // tunable WITHOUT a deploy

async function onFanoutHybrid({ postId, authorId }) {
  const n = await db.followers.count(authorId);

  if (n > CELEBRITY) return;   // no fan-out; readers will pull it

  await onFanout({ postId, authorId });
}

async function getFeedHybrid(userId, cursor, limit = 20) {
  const [precomputed, celebs] = await Promise.all([
    cache.lrange(`feed:${userId}`, cursor, limit),
    db.followees.celebrities(userId),        // usually a short list
  ]);

  const recent = await db.posts.recentFrom(celebs, limit);
  const merged = mergeByIdDesc(await db.posts.mget(precomputed), recent);

  return merged.slice(0, limit);
}

// ✗ OFFSET 20  → new posts arrive, the window slides, items repeat
// ✓ after_id   → stable regardless of what was inserted since

async function page(userId, afterId, limit = 20) {
  return db.posts.where({ feedOf: userId, idLessThan: afterId })
                 .orderByIdDesc()
                 .limit(limit);
}
